import System.Environment;import System.IO;import System.Directory;import Data.List
main=do t<-hIsTerminalDevice stdin;x<-getArgs;v<-lookupEnv"TODO_FILE_PATH";let{f=maybe"todo.md"id v;p="- [";q s=take 3s==p;w=writeFile f.unlines;k g=snd.mapAccumL(\n s->if q s then(n+1,g n s)else(n,s))1};e<-doesFileExist f;l<-if e then do{s<-readFile f;length s`seq`pure(lines s)}else pure[];i<-if t then pure(drop 1 x)else(if null x||head x=="add"then(:[])else words)<$>getContents;case(if null x then(if t then"list"else"add")else head x)of{"add"->w$l++map(\s->p++" ] "++s)i;"clear"->w[s|s<-l,take 5s/=p++"x]"];c|c`elem`["do","undo"]->w$k(\n s->if show n`elem`i then p++(if c=="do"then"x"else" ")++"] "++drop 6 s else s)l;"list"->mapM_ putStrLn$k(\n s->show n++" "++drop 2 s)l;_->putStrLn"todo [list|add|do|undo|clear]"}